def document():
    doc=dict(id='qa-reading-golden',title='QA · The Lantern Library (dữ liệu kiểm thử)',testType='practice',fullTest=False,duration=600,passages=[dict(id='p1',title='The Lantern Library',blocks=[dict(id='b1',type='heading',text='A library for the evening'),dict(id='b2',type='paragraph',text='The Lantern Library opened in 2018. It closes at nine in the evening, giving shift workers time to read. Its founder, Mara Lin, chose a quiet building beside the river. The library lends books free of charge. Visitors must bring a library card to borrow them. The writer considers this free access essential.'),dict(id='b3',type='paragraph',text='Section B\nIn 2020 the library introduced solar-powered reading lamps. Volunteers clean the panels every month. Energy costs fell after the lamps were installed. The library does not record the occupations of its visitors. Its website lists book groups and workshops, but says nothing about plans for a café.'),dict(id='b4',type='table',caption='Opening schedule',rows=[['Service','Day','Time'],['Book group','Monday','{{q10}}'],['Workshop','Saturday','10:00']]),dict(id='b5',type='flowchart',items=['Show your card','Choose a book','Record the loan','Return within {{q11}} days'])]),dict(id='p2',title='Community notice',blocks=[dict(id='b6',type='paragraph',text='The Monday book group begins at 18:00. Loans last fourteen days. Mara Lin coordinates book groups. Amir Dao maintains the solar panels. The roof carries the panels and a tank stores rainwater. The workshop teaches visitors to repair damaged books. People can join either the book group or the repair workshop without paying.'),dict(id='b7',type='diagram',src='data:image/png;base64,',alt='Original QA drawing: solar panels on the library roof, pipe and rainwater tank',caption='Sơ đồ tự biên soạn riêng để kiểm thử vùng trả lời',labels=[dict(questionId='q12',label='Vị trí 12',x=.30,y=.30)])])],groups=[],questions=[],sourceDocument=dict(source=dict(reference='qa-authored-fixture-v1',name='golden.json'),blocks=[]))
    def add(typ,prompt,opts=None,key=None,maxwords=2,pid='p1',quote=None,block='b2'):
        n=len(doc['questions'])+1;id='q'+str(n);gid='g'+str(n)
        options=[dict(id=id+'-'+label.replace(' ','-'),label=label,content=text) for label,text in (opts or [])]
        k=dict(status='UNVERIFIED',provenance='qa-authored-fixture-v1',optionIds=[id+'-'+x.replace(' ','-') for x in (key if isinstance(key,list) else [key])] if options else [],accepted=[] if options else [key])
        constraints=dict(maxWords=maxwords,maxNumbers=1,select=2 if typ=='multiple' else None)
